      tessera_scroll_info.offset_y = tessera_scroll;
      tessera_scroll_info.viewport_height = tessera_viewport;
      tessera_scroll_info.content_height = virtual_3_geometry_.total_extent();
      this->on_scroll(tessera_scroll_info);
