      const auto& tessera_source = state_items_;
      const std::size_t tessera_total = tessera_source.size();
      if (tessera_first > tessera_total) {
        tessera_first = tessera_total;
      }
      if (tessera_last > tessera_total) {
        tessera_last = tessera_total;
      }
      if (tessera_last < tessera_first) {
        tessera_last = tessera_first;
      }
      // Key/order hash first: an unchanged window allocates nothing and touches no node.
      std::uint64_t tessera_order = tessera::ui::kEffectHashSeed;
      std::size_t tessera_window = 0;
      for (std::size_t tessera_i = tessera_first; tessera_i < tessera_last; ++tessera_i) {
        const std::string& cell = tessera_source[tessera_i];
        tessera_order = tessera::ui::effect_hash(tessera_order, std::string_view(cell));
        ++tessera_window;
      }
      tessera_order = tessera::ui::effect_hash(tessera_order, static_cast<int>(tessera_first));
      tessera_order = tessera::ui::effect_hash(tessera_order, static_cast<int>(tessera_window));
