        virtual_6_hashes_ = std::move(tessera_next_hashes);
        virtual_6_set_ = std::move(tessera_next_set);
        virtual_6_keys_ = std::move(tessera_next_keys);
        virtual_6_count_ = tessera_next;
        virtual_6_first_ = tessera_first;
