      std::size_t tessera_slot = 0;
      for (std::size_t tessera_i = tessera_first; tessera_i < tessera_last; ++tessera_i) {
        if (tessera_slot == virtual_6_count_) {
          break;
        }
        apply_item_7(tessera_slot, tessera_source[tessera_i], tessera_i);
        ++tessera_slot;
      }
